column4:
let _ = data_roles_named_before_the_last_record;
if data_roles.len() < 2 {
    return vec![rewritten.to_vec()];
}
let mut roles_named_by_each_record: Vec<Vec<TransactionUnit>> =
    data_roles.iter().map(|data_role| vec![*data_role]).collect();
roles_named_by_each_record[0].extend(
    rewritten
        .iter()
        .copied()
        .filter(|identity| !matches!(identity, TransactionUnit::Data(_))),
);
